const DEFAULT_TERMS = 14;

/** A late percent: 0.00 to 999.99, with up to two decimals. */
const PCT = /^\d{1,3}(\.\d{1,2})?$/;

const DEFAULT_LATE_PCT = '0.00';

/** A policy date: yyyy-mm-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;

